using System.Net;
using System.Text.Json;
using WeatherApp.Models;

namespace WeatherApp.Services;

public class WeatherService : IWeatherService
{
    private readonly HttpClient _httpClient;
    private readonly string _apiKey;
    private readonly Random _random = new();

    public WeatherService(IHttpClientFactory httpClientFactory, IConfiguration config)
    {
        _httpClient = httpClientFactory.CreateClient();
        _apiKey = config["WeatherApiKey"] ?? throw new InvalidOperationException("API key not configured.");
        _httpClient.Timeout = TimeSpan.FromSeconds(10);
    }

    public async Task<WeatherResponse?> FetchWeatherAsync(string city)
    {
        if (string.IsNullOrWhiteSpace(city))
            throw new ArgumentException("City cannot be empty.");

        var url = $"https://api.openweathermap.org/data/2.5/weather?q={Uri.EscapeDataString(city)}&appid={_apiKey}&units=metric";

        int retryCount = 0;
        const int maxRetries = 3;
        int backoffMs = 1000;

        while (retryCount < maxRetries)
        {
            try
            {
                var response = await _httpClient.GetAsync(url);
                response.EnsureSuccessStatusCode();

                var json = await response.Content.ReadAsStringAsync();
                var weatherData = JsonSerializer.Deserialize<dynamic>(json);

                return new WeatherResponse
                {
                    Name = weatherData.weather[0].main,
                    Country = weatherData.sys?.country,
                    Temp = weatherData.main.temp,
                    Humidity = weatherData.main.humidity,
                    WindSpeed = weatherData.wind.speed,
                    Conditions = $"{weatherData.weather[0].main} ({weatherData.weather[0].description})"
                };
            }
            catch (HttpRequestException ex) when (ex.StatusCode == HttpStatusCode.TooManyRequests)
            {
                retryCount++;
                await Task.Delay(backoffMs);
                backoffMs *= 2; // Exponential backoff
                continue;
            }
            catch (HttpRequestException ex) when (ex.StatusCode == HttpStatusCode.NotFound)
            {
                throw new InvalidOperationException($"City '{city}' not found.");
            }
            catch (HttpRequestException ex) when (retryCount < maxRetries)
            {
                retryCount++;
                await Task.Delay(backoffMs);
                backoffMs *= 2;
            }
